// Vue 2 响应式简化实现
function defineReactive(obj, key, val) {
  const dep = new Dep(); // 依赖收集器
  Object.defineProperty(obj, key, {
    get() {
      if (Dep.target) {
        dep.depend(); // 收集依赖
      }
      return val;
    },
    set(newVal) {
      if (newVal === val) return;
      val = newVal;
      dep.notify(); // 触发更新
    }
  });
}

class Dep {
  static target = null;
  constructor() { this.subs = new Set(); }
  depend() { if (Dep.target) this.subs.add(Dep.target); }
  notify() { this.subs.forEach(w => w.update()); }
}

// Vue 3 Proxy实现
function reactive(target) {
  return new Proxy(target, {
    get(obj, key, receiver) {
      track(obj, key); // 收集依赖
      const result = Reflect.get(obj, key, receiver);
      if (typeof result === 'object') return reactive(result); // 惰性递归
      return result;
    },
    set(obj, key, value, receiver) {
      const result = Reflect.set(obj, key, value, receiver);
      trigger(obj, key); // 触发更新
      return result;
    },
    deleteProperty(obj, key) {
      const result = Reflect.deleteProperty(obj, key);
      trigger(obj, key);
      return result;
    }
  });
}

// 依赖收集
const targetMap = new WeakMap();
function track(target, key) {
  if (!activeEffect) return;
  let depsMap = targetMap.get(target);
  if (!depsMap) targetMap.set(target, (depsMap = new Map()));
  let dep = depsMap.get(key);
  if (!dep) depsMap.set(key, (dep = new Set()));
  dep.add(activeEffect);
}

function trigger(target, key) {
  const depsMap = targetMap.get(target);
  if (!depsMap) return;
  const dep = depsMap.get(key);
  if (dep) dep.forEach(effect => effect());
}

// computed实现
class ComputedRefImpl {
  constructor(getter) {
    this._dirty = true;
    this._value = undefined;
    this.effect = effect(getter, {
      lazy: true,
      scheduler: () => { this._dirty = true; } // 依赖变化时标记脏
    });
  }
  get value() {
    if (this._dirty) {
      this._value = this.effect(); // 惰性求值
      this._dirty = false;
    }
    return this._value;
  }
}
